"""sci_review.py — 数据异常复盘与改进建议 v0（Phase 3c）

流程：
  1. --build   取课题日志与数据异常，生成 review_jobs.json（交 LLM/人做 KB 检索与归因）
  2. LLM 按 schema 产出 review.json：每条建议含 cause/action/evidence[{page,quote}]
  3. --merge   逐条校验证据页存在、quote 是页面正文连续子串，渲染 review.md

用法：
  python tools/sci_review.py --project "课题A" --data <ecsa_result.json> --build
  python tools/sci_review.py --project "课题A" --merge <review.json>
  python tools/sci_review.py --selftest

🔴 建议必须挂库内证据（页面 + 原文），校验不过的条目丢弃；
   **不拿通用常识替代库内证据**，找不到证据就少写。
"""

import argparse
import datetime
import json
import os
import re
import sys

TOOLS_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, TOOLS_DIR)

import kb_lib as K  # noqa: E402
K.console_encoding()

CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"
PAGE_DIRS = ("concepts", "sources", "topics", "outputs", "entities")


def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def progress_root(cfg):
    rel = (cfg.get("sci") or {}).get("progress_dir") or "projects/sci-assistant/progress"
    return rel if os.path.isabs(rel) else os.path.join(K.VAULT, rel)


def project_dir(cfg, slug):
    return os.path.join(progress_root(cfg), slug)


def load_project(cfg, slug):
    import yaml
    p = os.path.join(project_dir(cfg, slug), "project.yaml")
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 课题不存在: {slug}")
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def load_logs(cfg, slug):
    d = os.path.join(project_dir(cfg, slug), "log")
    out = []
    if not os.path.isdir(d):
        return out
    for fn in sorted(os.listdir(d)):
        if not fn.endswith(".md"):
            continue
        txt = K.read_text(os.path.join(d, fn))
        fm, body = K.split_frontmatter(txt)
        try:
            import yaml
            meta = yaml.safe_load(fm) or {}
        except Exception:
            meta = {}
        out.append({"file": fn, "meta": meta, "body": (body or "").strip()})
    return out


# ---------------------------------------------------------------- 构建任务

SCHEMA = """复盘 schema：
{
  "project": "<slug>",
  "summary": "一句话复盘结论（基于事实，不夸大）",
  "advice": [
    {
      "text": "建议做什么（具体、可执行）",
      "cause": "为什么会出这个问题（基于库内证据的归因）",
      "action": "下一步动作（含判定标准）",
      "strength": "strong|mixed|single-source|secondhand|unknown",
      "evidence": [{"page": "sources/xxx 或 concepts/xxx", "quote": "页面里的连续原文"}]
    }
  ]
}
🔴 evidence 里的 page 必须是库内真实页面（concepts/sources/topics/outputs），
   quote 必须是该页正文的连续子串；找不到证据就不要写这条建议。"""


def build_jobs(cfg, slug, data_path=None):
    proj = load_project(cfg, slug)
    logs = load_logs(cfg, slug)
    facts = {"project": slug, "title": proj.get("title"),
             "goal": proj.get("goal"), "direction": proj.get("direction"),
             "logs": [{"id": l["meta"].get("exp_id"), "title": l["meta"].get("title"),
                       "result": l["meta"].get("result"), "body": l["body"][:1200]}
                      for l in logs]}
    if data_path:
        with open(data_path, "r", encoding="utf-8") as f:
            facts["data"] = json.load(f)
    return {"generated_at": datetime.date.today().isoformat(),
            "schema": SCHEMA, "facts": facts,
            "instructions": ("针对 facts 中的异常，用 kb_route.py / kb_search.py 检索库内证据，"
                             "给出 3-5 条改进建议；每条必须带 page+quote；"
                             "先写 cause 再写 action；找不到证据的就不要写。")}


# ---------------------------------------------------------------- 校验

def norm_ws(s):
    return re.sub(r"\s+", " ", str(s or "")).strip()


def resolve_page(name, vault=None):
    """把 page 引用解析成库内路径；解析不到返回 None。"""
    vault = vault or K.VAULT
    if not name:
        return None
    n = str(name).strip().strip("[]")
    n = re.sub(r"^\[\[|\]\]$", "", n)
    n = n.split("|")[0].split("#")[0].strip()
    if n.startswith("wiki/"):
        cands = [n]
    else:
        n2 = n[:-3] if n.endswith(".md") else n
        cands = [f"wiki/{n2}.md"] + [f"wiki/{d}/{n2}.md" for d in PAGE_DIRS]
    for c in cands:
        if os.path.isfile(os.path.join(vault, c)):
            return c
    return None


def page_body(rel, vault=None, pages=None):
    if pages is not None:
        return norm_ws(pages.get(rel))
    vault = vault or K.VAULT
    p = os.path.join(vault, rel)
    return norm_ws(K.read_text(p)) if os.path.isfile(p) else ""


def page_strength(rel, vault=None, pages=None):
    """从页面 frontmatter 读 evidence_base；读不到返回 unknown。"""
    try:
        if pages is not None:
            txt = pages.get(rel) or ""
        else:
            txt = K.read_text(os.path.join(vault or K.VAULT, rel))
        fm, _ = K.split_frontmatter(txt)
        import yaml
        return (yaml.safe_load(fm) or {}).get("evidence_base") or "unknown"
    except Exception:
        return "unknown"


def validate_advice(advice, vault=None, pages=None):
    clean, stats = [], {"checked": 0, "failed": 0, "dropped": 0}
    for a in advice or []:
        ev_ok = []
        for ev in a.get("evidence") or []:
            rel = resolve_page(ev.get("page"), vault)
            stats["checked"] += 1
            if not rel:
                stats["failed"] += 1
                continue
            q = norm_ws(ev.get("quote"))
            if not q or q not in page_body(rel, vault, pages):
                stats["failed"] += 1
                continue
            ev_ok.append({"page": rel, "quote": ev.get("quote")})
        if not ev_ok:
            stats["dropped"] += 1
            continue
        strength = a.get("strength") or page_strength(ev_ok[0]["page"], vault, pages)
        clean.append({"text": a.get("text") or "", "cause": a.get("cause") or "",
                      "action": a.get("action") or "", "strength": strength,
                      "evidence": ev_ok})
    return clean, stats


# ---------------------------------------------------------------- 渲染

def render_review(proj, logs, data, summary, advice, stats):
    L = [f"# 复盘：{proj.get('title')}", ""]
    L.append(f"> 生成于 {datetime.date.today().isoformat()} ｜ 课题 `{proj.get('slug')}` ｜ "
             f"建议 {len(advice)} 条 ｜ 证据校验 {stats['checked']} 条 / 失败 {stats['failed']}")
    L.append("")
    if summary:
        L.append(f"**一句话结论**：{summary}")
        L.append("")
    L.append("## 一、事实")
    L.append("")
    for l in logs:
        L.append(f"- {l['meta'].get('date')} ｜ {l['meta'].get('exp_id')} ｜ "
                 f"**{l['meta'].get('title')}** ｜ 结果：{l['meta'].get('result')}")
        if l["body"]:
            L.append(f"  - {l['body'].splitlines()[0][:160]}")
    if data:
        L.append("")
        L.append("数据异常：")
        L.append("")
        L.append("```json")
        L.append(json.dumps(data, ensure_ascii=False, indent=2)[:1500])
        L.append("```")
    L.append("")
    L.append("## 二、改进建议")
    L.append("")
    for i, a in enumerate(advice, 1):
        L.append(f"### {i}. {a['text']}")
        L.append("")
        if a.get("cause"):
            L.append(f"- **原因**：{a['cause']}")
        if a.get("action"):
            L.append(f"- **下一步**：{a['action']}")
        L.append(f"- **证据强度**：{a.get('strength')}")
        for ev in a["evidence"]:
            L.append(f"- 证据：`{ev['page']}` ｜ {ev['quote']}")
        L.append("")
    L.append("## 三、边界")
    L.append("")
    L.append("- 建议只基于所列库内证据；证据不足的条目已在合并时丢弃。")
    L.append("- 归因是「可能原因」，不是已证实的因果；执行前请核对原始数据。")
    L.append("")
    return "\n".join(L)


# ---------------------------------------------------------------- 自检

def _write_selftest_vault(tmp):
    for rel, txt in _SELFTEST_PAGES.items():
        p = os.path.join(tmp, rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8", newline="\n") as f:
            f.write(txt)


_SELFTEST_PAGES = {
    "wiki/concepts/ECSA.md": "---\nevidence_base: mixed\ntype: concept\n---\n"
                             "ECSA 计算需要至少两个扫速，否则斜率不可拟合。",
    "wiki/sources/paper.md": "---\ntype: source\n---\nCdl 由 Δj/2 对扫速拟合得到。",
}


def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    proj = {"slug": "p1", "title": "测试课题"}
    logs = [{"meta": {"date": "2026-10-20", "exp_id": "E001", "title": "T",
                      "result": "failed"}, "body": "斜率退化为机器零"}]
    advice = [
        {"text": "至少两个扫速", "cause": "单点无法拟合", "action": "补 5/7/10 mV/s",
         "evidence": [{"page": "concepts/ECSA", "quote": "至少两个扫速"}]},
        {"text": "伪造证据", "cause": "x", "action": "y",
         "evidence": [{"page": "concepts/ECSA", "quote": "这句不在页面里"}]},
        {"text": "页面不存在", "cause": "x", "action": "y",
         "evidence": [{"page": "concepts/不存在", "quote": "至少两个扫速"}]},
    ]
    tmp = K.make_temp_dir(prefix="sci_review_")
    try:
        _write_selftest_vault(tmp)
        clean, stats = validate_advice(advice, vault=tmp)
        chk("校验：合法证据保留", len(clean) == 1 and clean[0]["text"] == "至少两个扫速")
        chk("校验：伪造 quote 与缺页均失败",
            stats["checked"] == 3 and stats["failed"] == 2 and stats["dropped"] == 2)
        chk("校验：证据强度取自页面", clean[0]["strength"] == "mixed")
        chk("解析：[[concepts/ECSA]] 归一",
            resolve_page("[[concepts/ECSA]]", tmp) == "wiki/concepts/ECSA.md")
        md = render_review(proj, logs, {"r2": 1e-16}, "结论", clean, stats)
        chk("渲染：含事实/建议/证据",
            "## 一、事实" in md and "## 二、改进建议" in md and
            "concepts/ECSA.md" in md and "至少两个扫速" in md)
        chk("渲染：标注证据强度", "mixed" in md)
    finally:
        K.remove_temp_dir(tmp)

    jobs = build_jobs_from(proj, logs, {"r2": 1e-16})
    chk("任务：含 schema 与 facts",
        jobs["schema"].startswith("复盘 schema") and jobs["facts"]["project"] == "p1")
    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


def build_jobs_from(proj, logs, data=None):
    facts = {"project": proj.get("slug"), "title": proj.get("title"),
             "logs": [{"id": l["meta"].get("exp_id"), "title": l["meta"].get("title"),
                       "result": l["meta"].get("result"), "body": l["body"]} for l in logs]}
    if data is not None:
        facts["data"] = data
    return {"generated_at": datetime.date.today().isoformat(),
            "schema": SCHEMA, "facts": facts}


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="数据异常复盘与建议（Phase 3c v0）")
    ap.add_argument("--project", help="课 slug")
    ap.add_argument("--data", default=None, help="数据异常 JSON（可选）")
    ap.add_argument("--build", action="store_true", help="生成 review_jobs.json")
    ap.add_argument("--merge", default=None, help="合并 LLM 产出的 review.json")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not args.project:
        ap.print_help()
        return 1

    cfg = load_config()
    proj = load_project(cfg, args.project)
    proj["slug"] = args.project
    logs = load_logs(cfg, args.project)
    data = None
    if args.data:
        with open(args.data, "r", encoding="utf-8") as f:
            data = json.load(f)

    out_dir = os.path.join(project_dir(cfg, args.project), "review")

    if args.build:
        jobs = build_jobs(cfg, args.project, args.data)
        os.makedirs(out_dir, exist_ok=True)
        p = os.path.join(out_dir, "review_jobs.json")
        with open(p, "w", encoding="utf-8", newline="\n") as f:
            json.dump(jobs, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print(f"[ok] 复盘任务：{len(jobs['facts']['logs'])} 条日志 → {os.path.relpath(p, K.VAULT)}")
        print("     下一步：按 schema 产出 review.json（每条建议挂 page+quote），再 --merge")
        return 0

    if not args.merge:
        ap.print_help()
        return 1

    with open(args.merge, "r", encoding="utf-8") as f:
        payload = json.load(f)
    advice, stats = validate_advice(payload.get("advice") or [])
    md = render_review(proj, logs, data, payload.get("summary") or "", advice, stats)
    os.makedirs(out_dir, exist_ok=True)
    p_md = os.path.join(out_dir, "review.md")
    with open(p_md, "w", encoding="utf-8", newline="\n") as f:
        f.write(md + "\n")
    p_js = os.path.join(out_dir, "review_validated.json")
    with open(p_js, "w", encoding="utf-8", newline="\n") as f:
        json.dump({"summary": payload.get("summary"), "advice": advice,
                   "stats": stats}, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print(f"[ok] 复盘：保留 {len(advice)} 条建议；证据校验 {stats['checked']} 条，"
          f"失败 {stats['failed']}，整条丢弃 {stats['dropped']}")
    print(f"     输出：{os.path.relpath(p_md, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
